                ctx.fillStyle = '#050505';
                ctx.fillRect(0, 0, 256, 256);
                ctx.fillStyle = '#ffbb22';
                ctx.font = 'bold 180px Arial';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.shadowColor = '#ffbb22';
                ctx.shadowBlur = 20;
                ctx.fillText(text, 128, 128);
                tex.needsUpdate = true;
            }
