function buildOfficeFloorWalls(floorY, shaftX, shaftZ, nodes, sitTargets) {
    const halfW = WORLD.BUILDING_WIDTH / 2;
    const halfD = WORLD.BUILDING_DEPTH / 2;
    const wallHeight = WORLD.FLOOR_HEIGHT;

    // Hallway ring around shaft - add corner nodes
    const hallNodes = ['hallS', 'hallSE', 'hallE', 'hallNE', 'hallN', 'hallNW', 'hallW', 'hallSW'];
    for (const node of hallNodes) {
        let pos;
        switch(node) {
            case 'hallS': pos = new THREE.Vector3(0, floorY, halfD + 1); break;
            case 'hallSE': pos = new THREE.Vector3(halfW/2, floorY, halfD + 1); break;
            case 'hallE': pos = new THREE.Vector3(halfW/2, floorY, 0); break;
            case 'hallNE': pos = new THREE.Vector3(halfW/2, floorY, -halfD/2); break;
            case 'hallN': pos = new THREE.Vector3(0, floorY, -halfD - 1); break;
            case 'hallNW': pos = new THREE.Vector3(-halfW/2, floorY, -halfD/2); break;
            case 'hallW': pos = new THREE.Vector3(-halfW/2, floorY, 0); break;
            case 'hallSW': pos = new THREE.Vector3(-halfW/2, floorY, halfD + 1); break;
        }
        if (pos) nodes[node] = pos;
